import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes } from 'react'
import styles from './code.module.css'

export interface CodeProps extends HTMLAttributes<HTMLElement> {
  size?: 'sm' | 'md'
}

export function Code({ size = 'md', className, children, ...props }: CodeProps) {
  return (
    <code
      data-size={size}
      className={cn(styles['code'], className as string | undefined)}
      {...props}
    >
      {children}
    </code>
  )
}

@layer cascivo.component {
  .code {
    font-family: var(--cascivo-font-mono);
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-indicator);
    padding-block: 0.0625rem;
    padding-inline: var(--cascivo-space-1);
    white-space: nowrap;

    &[data-size='sm'] {
      font-size: var(--cascivo-text-xs);
    }

    &[data-size='md'] {
      font-size: var(--cascivo-text-sm);
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Code',
  description: 'Inline code span for identifiers, commands, and short snippets',
  category: 'display',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: ['sm', 'md'],
  props: [
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md'",
      required: false,
      default: 'md',
    },
  ],
  tokens: [
    '--cascivo-font-mono',
    '--cascivo-color-text',
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-radius-indicator',
    '--cascivo-text-xs',
    '--cascivo-text-sm',
  ],
  accessibility: {
    role: 'code',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    { title: 'Default', code: '<Code>npx cascivo add button</Code>' },
    {
      title: 'In a sentence',
      code: '<Text>Run <Code>vp check</Code> before committing.</Text>',
      description: 'Sits inline with surrounding text',
    },
    { title: 'Small', code: '<Code size="sm">--cascivo-color-accent</Code>' },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['typography', 'code', 'inline', 'mono'],
  intent: {
    whenToUse: [
      'Marking up an inline identifier, command, path, or token within prose',
      'Distinguishing literal code from surrounding text with a monospace span',
    ],
    whenNotToUse: [
      'Multi-line code blocks with syntax highlighting — use a <pre> block',
      'Keyboard shortcuts the user should press — use Kbd',
    ],
    antiPatterns: [
      {
        bad: '<Code>Press Cmd+K</Code>',
        good: '<Kbd>⌘</Kbd> <Kbd>K</Kbd>',
        why: 'Code marks literal code; key presses are semantically Kbd',
      },
    ],
    related: [
      {
        name: 'Kbd',
        relationship: 'alternative',
        reason: 'Kbd is for keys to press, not code to read',
      },
      {
        name: 'Prose',
        relationship: 'pairs-with',
        reason: 'Prose styles inline <code> automatically in authored content',
      },
    ],
    a11yRationale:
      'Renders a native <code> element so assistive tech can expose the content as code; relies on monospace and surface, not color alone, to distinguish it',
    flexibility: [
      {
        area: 'size',
        level: 'flexible',
        note: 'sm fits dense UI; md matches body text',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Font and surface must resolve to --cascivo-font-mono and --cascivo-* tokens',
      },
    ],
  },
}
